    """ Calculate population standard deviation for a population.

    population standard deviation: S = sqrt(mean | x - μ |)
    S: S = standard deviation
    μ: μ = population mean
    x: x = element in population
    >>> population_standard_deviation([1.0, 2.0, 3.0, 4.0])
    1.4142135623730951
    """
    if len(numbers) > 0:
        mean = sum(numbers) / len(numbers)
        std = sum([((num - mean) ** 2) for num in numbers]) / len(numbers)
        return std ** 0.5
    else:
        return 0.0


